import { Router } from "express";
import { rooms, findRoom, bookingsForRoom } from "../store.js";
import { availabilityForDay } from "../lib/availability.js";
import { ValidationError } from "../lib/validate.js";

export const roomsRouter = Router();

roomsRouter.get("/", (_req, res) => {
  res.json({ rooms });
});

roomsRouter.get("/:id/availability", (req, res) => {
  try {
    const room = findRoom(req.params.id);
    if (!room) {
      res.status(404).json({ error: "salle inconnue" });
      return;
    }

    const { date } = req.query;
    if (typeof date !== "string") {
      throw new ValidationError("date requise au format YYYY-MM-DD");
    }
    const dayStart = Date.parse(`${date}T00:00:00.000Z`);
    if (!/^\d{4}-\d{2}-\d{2}$/.test(date) ||
        Number.isNaN(dayStart) ||
        new Date(dayStart).toISOString().slice(0, 10) !== date) {
      throw new ValidationError("date invalide : date");
    }

    res.json({ roomId: room.id, date, slots: availabilityForDay(bookingsForRoom(room.id), date) });
  } catch (err) {
    if (err instanceof ValidationError) {
      res.status(err.status).json({ error: err.message });
      return;
    }
    throw err;
  }
});

roomsRouter.get("/:id", (req, res) => {
  const room = findRoom(req.params.id);
  if (!room) {
    res.status(404).json({ error: "salle inconnue" });
    return;
  }
  res.json({ room, bookings: bookingsForRoom(room.id) });
});

import type { Booking } from "../store.js";

export interface TimeSlot {
  startsAt: string;
  endsAt: string;
}

function isoUtc(timestamp: number): string {
  return new Date(timestamp).toISOString().replace(".000Z", "Z");
}

export function availabilityForDay(roomBookings: Booking[], date: string): TimeSlot[] {
  const dayStart = Date.parse(`${date}T00:00:00.000Z`);
  const dayEnd = dayStart + 24 * 60 * 60 * 1000;
  const busy = roomBookings
    .map((booking) => ({
      startsAt: Math.max(Date.parse(booking.startsAt), dayStart),
      endsAt: Math.min(Date.parse(booking.endsAt), dayEnd)
    }))
    .filter((slot) => slot.startsAt < slot.endsAt)
    .sort((a, b) => a.startsAt - b.startsAt);

  const merged: Array<{ startsAt: number; endsAt: number }> = [];
  for (const slot of busy) {
    const previous = merged.at(-1);
    if (previous && slot.startsAt <= previous.endsAt) {
      previous.endsAt = Math.max(previous.endsAt, slot.endsAt);
    } else {
      merged.push({ ...slot });
    }
  }

  const free: TimeSlot[] = [];
  let cursor = dayStart;
  for (const slot of merged) {
    if (cursor < slot.startsAt) {
      free.push({ startsAt: isoUtc(cursor), endsAt: isoUtc(slot.startsAt) });
    }
    cursor = Math.max(cursor, slot.endsAt);
  }
  if (cursor < dayEnd) {
    free.push({ startsAt: isoUtc(cursor), endsAt: isoUtc(dayEnd) });
  }
  return free;
}

export default availabilityForDay;

